// ========== URL'DEN DOMAIN ÇIKAR ==========
function getDomainName(fullUrl) {
  if (!fullUrl) return '';
  const match = fullUrl.match(/https?:\/\/([^\/]+)/i);
  if (!match || !match[1]) return '';
  const parts = match[1].toLowerCase().split('.');
  for (const part of parts) {
    if (part.length > 3 && !subdomains.includes(part)) {
      return part;
    }
  }
  for (const part of parts) {
    if (part.length > 2 && part !== 'www') {
      return part;
    }
  }
  return '';
}

// ========== COMPANY NAME ÇIKAR ==========
function extractCompanyName(domain) {
  if (!domain || domain.length < 2) return 'Bilinmeyen';
  domain = domain.toLowerCase().replace(/-/g, '');
  if (knownDomains[domain]) return knownDomains[domain];
  const sortedWords = Object.keys(wordMap).sort((a, b) => b.length - a.length);
  let remaining = domain;
  let parts = [];
  while (remaining.length > 0) {
    let found = false;
    for (const word of sortedWords) {
      if (remaining.startsWith(word)) {
        parts.push(wordMap[word]);
        remaining = remaining.slice(word.length);
        found = true;
        break;
      }
    }
    if (!found) {
      const char = remaining.charAt(0);
      remaining = remaining.slice(1);
      if (parts.length > 0 && parts[parts.length - 1].length <= 3) {
        parts[parts.length - 1] += char;
      } else {
        parts.push(char);
      }
    }
  }
  return parts.map(p => {
    if (p.toLowerCase() === 've') return 've';
    if (p.length === 1) return p.toUpperCase();
    return p.charAt(0).toUpperCase() + p.slice(1);
  }).join(' ').trim() || 'Bilinmeyen';
}

// ========== EXTRACT EMAIL ==========
function extractEmail(html) {
  const matches = html.match(emailRegex) || [];
  const validEmails = matches.filter(email => {
    const lower = email.toLowerCase();
    return !lower.match(/\.(png|jpg|jpeg|gif|css|js|svg)$/) && !lower.includes('wixpress') && !lower.includes('sentry') && !lower.includes('example');
  });
  return [...new Set(validEmails)][0] || null;
}

// ========== EXTRACT PHONE ==========
function extractPhone(html) {
  const matches = html.match(phoneRegex) || [];
  if (matches.length === 0) return null;
  let phone = matches[0].replace(/[^0-9+]/g, '');
  if (!phone.startsWith('+90') && !phone.startsWith('0') && phone.length === 10) phone = '0' + phone;
  if (phone.startsWith('0') && phone.length === 11) {
    return phone.slice(0,4) + ' ' + phone.slice(4,7) + ' ' + phone.slice(7,9) + ' ' + phone.slice(9,11);
  }
  return phone;
}

// ========== MAIN ==========
const email = extractEmail(html);
const phone = extractPhone(html);
const domainName = getDomainName(url);
let companyName = extractCompanyName(domainName);

if (companyName === 'Bilinmeyen' && email && email.includes('@')) {
  const emailDomain = email.split('@')[1];
  if (!emailDomain.includes('gmail') && !emailDomain.includes('hotmail') && !emailDomain.includes('yahoo')) {
    companyName = extractCompanyName(emailDomain.split('.')[0]);
  }
}

