    'Lokasyon': prevData['Lokasyon'],
    'Category': prevData['Category'],
    'Phone': prevData['Phone'] || '',
    'Email': prevData['Email'],
    'Website': prevData['Website']
  }
}];

// Google Search sonuçlarından URL'leri çıkar
const results = [];

// Get Today Sector'dan lokasyon ve sektör al
let lokasyon = '';
let sektor = '';
try { 
  lokasyon = $('Get Today Sector').item.json.Lokasyon || ''; 
  sektor = $('Get Today Sector').item.json.Sektor || '';
} catch(e) {}

// items[0].json bir array olarak geliyor
const allData = Array.isArray(items[0].json) ? items[0].json : items.map(i => i.json);

for (const data of allData) {
  const organicResults = data.organicResults || [];

  for (const result of organicResults) {
    if (result.url && 
        !result.url.includes('google.com') && 
        !result.url.includes('youtube.com') &&
        !result.url.includes('facebook.com') &&
        !result.url.includes('instagram.com') &&
        !result.url.includes('twitter.com') &&
        !result.url.includes('linkedin.com') &&
        !result.url.includes('sahibinden.com') &&
        !result.url.includes('sikayetvar.com')) {
      results.push({
        json: {
          url: result.url,
          title: result.title || '',
          description: result.description || '',
          lokasyon: lokasyon,
          sektor: sektor
        }
      });
    }
  }
}

// Duplicate URL'leri kaldır (domain bazlı)
const seen = new Set();
const unique = results.filter(item => {
  try {
    const domain = item.json.url.match(/https?:\/\/([^\/]+)/i)[1].replace('www.', '');
    if (seen.has(domain)) return false;
    seen.add(domain);
    return true;
  } catch {
    return false;
  }
});

// Max 30 işletme limiti
return unique.slice(0, 30);

